            case rpc::modes::ModesResult_Result_RESULT_MODE_NOT_FOUND:
                return mavsdk::Modes::Result::ModeNotFound;
            case rpc::modes::ModesResult_Result_RESULT_MODES_NOT_KNOWN_YET:
